package org.joda.time.field;

import java.io.*;
import java.math.*;
import java.util.*;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.IllegalFieldValueException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FieldUtils.safeMultiply
 */
public class FieldUtils_safeMultiply_TriageGen1Test {

    @Test
    public void testSafeMultiply_CaseNegativeOne() {
        assertEquals(-10L, FieldUtils.safeMultiply(10L, -1));
        assertEquals(10L, FieldUtils.safeMultiply(-10L, -1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, -1));
    }

    @Test
    public void testSafeMultiply_CaseZero() {
        assertEquals(0L, FieldUtils.safeMultiply(10L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(-10L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 0));
    }

    @Test
    public void testSafeMultiply_CaseOne() {
        assertEquals(10L, FieldUtils.safeMultiply(10L, 1));
        assertEquals(-10L, FieldUtils.safeMultiply(-10L, 1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 1));
    }

    @Test
    public void testSafeMultiply_NormalMultiplication() {
        assertEquals(20L, FieldUtils.safeMultiply(10L, 2));
        assertEquals(-20L, FieldUtils.safeMultiply(10L, -2));
        assertEquals(20L, FieldUtils.safeMultiply(-10L, -2));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 5));
    }

    @Test
    public void testSafeMultiply_OverflowPositive() {
        // Long.MAX_VALUE is 9223372036854775807L
        // Multiplying by 2 should overflow
        long val1 = Long.MAX_VALUE / 2 + 1;
        int val2 = 2;
        // val1 * 2 will be > Long.MAX_VALUE
        try {
            FieldUtils.safeMultiply(val1, val2);
            fail("Expected ArithmeticException due to overflow");
        } catch (ArithmeticException e) {
            assertTrue(e.getMessage().contains("Multiplication overflows a long"));
        }
    }

    @Test
    public void testSafeMultiply_OverflowNegative() {
        // Long.MIN_VALUE is -9223372036854775808L
        // Multiplying by 2 should overflow
        long val1 = Long.MIN_VALUE / 2 - 1;
        int val2 = 2;
        try {
            FieldUtils.safeMultiply(val1, val2);
            fail("Expected ArithmeticException due to overflow");
        } catch (ArithmeticException e) {
            assertTrue(e.getMessage().contains("Multiplication overflows a long"));
        }
    }

    @Test
    public void testSafeMultiply_EdgeCaseLargeValues() {
        // Test near boundaries that don't overflow
        assertEquals(Long.MAX_VALUE, FieldUtils.safeMultiply(Long.MAX_VALUE, 1));
        assertEquals(Long.MIN_VALUE, FieldUtils.safeMultiply(Long.MIN_VALUE, 1));

        // Large multiplication that stays within Long bounds
        long val1 = 1_000_000_000L;
        int val2 = 1_000_000;
        assertEquals(1_000_000_000_000_000L, FieldUtils.safeMultiply(val1, val2));
    }
}
